import{_ as e,o as a,c as o,ax as r}from"./chunks/framework.Bnt0oLax.js";const p=JSON.parse('{"title":"Customization Guardrails","description":"Decision guide for choosing a customization approach before you start — ranks no-code configuration, custom widgets, and other options by how safely they survive platform updates","frontmatter":{"description":"Decision guide for choosing a customization approach before you start — ranks no-code configuration, custom widgets, and other options by how safely they survive platform updates"},"headers":[],"relativePath":"custom-widgets/v2/customization-guardrails.md","filePath":"custom-widgets/v2/customization-guardrails.md"}'),s={name:"custom-widgets/v2/customization-guardrails.md"};function i(n,t,d,l,c,h){return a(),o("div",null,[...t[0]||(t[0]=[r('<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /docs/custom-widgets/v2/customization-guardrails.md for this page in Markdown format</div><h1 id="customization-guardrails" tabindex="-1">Customization Guardrails <a class="header-anchor" href="#customization-guardrails" aria-label="Permalink to &quot;Customization Guardrails&quot;">​</a></h1><p>There are many ways to customize a Gainsight community — from no-code configuration to custom widgets, scripts, and stylesheets. Not all approaches are equally safe. Some customizations work reliably across platform updates, while others can break when the platform evolves.</p><p>This page helps you choose the right approach for each customization need, so your work stays stable and maintainable.</p><h2 id="customization-tiers" tabindex="-1">Customization Tiers <a class="header-anchor" href="#customization-tiers" aria-label="Permalink to &quot;Customization Tiers&quot;">​</a></h2><p>Every customization falls into one of three tiers based on how likely it is to survive platform changes.</p><h3 id="safe" tabindex="-1">Safe <a class="header-anchor" href="#safe" aria-label="Permalink to &quot;Safe&quot;">​</a></h3><p>These approaches are fully supported and designed to be stable across platform updates.</p><table tabindex="0"><thead><tr><th>Approach</th><th>Notes</th></tr></thead><tbody><tr><td>Out-of-the-box configuration and widgets</td><td>No code required — the safest option</td></tr><tr><td>Custom pages using supported widgets</td><td>Built with the No-Code Builder</td></tr><tr><td>SSI header/footer includes</td><td>Isolated from app internals — see <a href="#ssi-header-and-footer">SSI Header and Footer</a> below</td></tr><tr><td>Custom widgets, scripts, and stylesheets via Developer Studio</td><td>Built with the supported extension framework</td></tr></tbody></table><h3 id="use-with-caution" tabindex="-1">Use with Caution <a class="header-anchor" href="#use-with-caution" aria-label="Permalink to &quot;Use with Caution&quot;">​</a></h3><p>These approaches are allowed but need care to avoid fragile results.</p><table tabindex="0"><thead><tr><th>Approach</th><th>Conditions</th></tr></thead><tbody><tr><td>Custom CSS</td><td>Styling only — no structural manipulation. See <a href="#custom-css">Custom CSS</a> below</td></tr><tr><td>Custom JavaScript</td><td>Simple scripting that does not manipulate the DOM or degrade performance</td></tr><tr><td>Custom icons</td><td>Allowed</td></tr></tbody></table><h3 id="avoid" tabindex="-1">Avoid <a class="header-anchor" href="#avoid" aria-label="Permalink to &quot;Avoid&quot;">​</a></h3><p>These approaches are not supported and are likely to break during platform updates. If your use case requires one of these, treat it as a product enhancement request rather than a customization.</p><table tabindex="0"><thead><tr><th>Approach</th><th>Why It Breaks</th></tr></thead><tbody><tr><td>DOM manipulation (moving, re-parenting, or copying elements)</td><td>Conflicts with the platform&#39;s rendering engine (Preact/hydration), causing duplicate elements or visual glitches</td></tr><tr><td>Changing core interaction behavior (like buttons, reply threading, expand/collapse)</td><td>These are product behaviors, not styling — changes here create unpredictable side effects</td></tr><tr><td>JavaScript redirects or non-standard navigation changes</td><td>High risk of breaking standard routing</td></tr><tr><td>Scripts that depend on internal DOM structure or CSS class names</td><td>Internal class names and DOM structure change without notice during platform updates</td></tr></tbody></table><h2 id="non-negotiables" tabindex="-1">Non-Negotiables <a class="header-anchor" href="#non-negotiables" aria-label="Permalink to &quot;Non-Negotiables&quot;">​</a></h2><p>These are hard boundaries. Do not attempt these as customizations under any circumstances.</p><ul><li><strong>Do not move or restructure elements rendered by the platform.</strong> The platform uses Preact with hydration. Third-party scripts that move elements can race against the rendering engine, causing duplicate elements or visual glitches that are difficult to diagnose.</li><li><strong>Do not implement custom &quot;create post&quot; or &quot;create topic&quot; flows.</strong> These are core platform behaviors with complex state management. If the out-of-the-box flow does not meet your needs, raise it as a product enhancement request.</li><li><strong>Do not override core UX behaviors via CSS or JavaScript</strong> (for example: non-standard like button behavior, custom reply toggles). These should be evaluated as product changes.</li></ul><h2 id="custom-css" tabindex="-1">Custom CSS <a class="header-anchor" href="#custom-css" aria-label="Permalink to &quot;Custom CSS&quot;">​</a></h2><p><strong>Principle:</strong> CSS is for styling, not for structure or behavior.</p><h3 id="what-works" tabindex="-1">What Works <a class="header-anchor" href="#what-works" aria-label="Permalink to &quot;What Works&quot;">​</a></h3><ul><li>Colors, typography, spacing, borders, shadows</li><li>Minor layout tweaks that do not reflow core components</li><li>Component-level styling scoped to a specific component boundary</li></ul><h3 id="what-to-avoid" tabindex="-1">What to Avoid <a class="header-anchor" href="#what-to-avoid" aria-label="Permalink to &quot;What to Avoid&quot;">​</a></h3><ul><li><strong>Hiding core UI elements</strong> — Risks accessibility issues and unexpected regressions. This includes hiding platform controls like the &quot;send private message&quot; button.</li><li><strong>Layout rewrites that assume specific DOM structure</strong> — Internal DOM structure changes between platform releases</li><li><strong>Broad modifications to shared components</strong> — Styles targeting components used across multiple pages or modules can cause unintended side effects</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Custom CSS that goes beyond styling (hiding elements, restructuring layouts, overriding behavior) is not covered by standard platform support. If the platform updates its UI and your CSS breaks, the fix is on the customization side.</p></div><h2 id="third-party-scripts" tabindex="-1">Third-Party Scripts <a class="header-anchor" href="#third-party-scripts" aria-label="Permalink to &quot;Third-Party Scripts&quot;">​</a></h2><p>Third-party scripts can be loaded on every page, so they must be written defensively and never assume DOM stability.</p><h3 id="what-works-1" tabindex="-1">What Works <a class="header-anchor" href="#what-works-1" aria-label="Permalink to &quot;What Works&quot;">​</a></h3><ul><li><strong>Analytics and tag managers</strong> — Non-blocking, async scripts (Google Analytics, Segment, etc.)</li><li><strong>Isolated UI additions</strong> — Completely self-contained elements like chat widgets or feedback modals that do not touch the platform DOM</li><li><strong>A/B testing frameworks</strong> — As long as they do not manipulate core platform elements</li></ul><h3 id="what-to-avoid-1" tabindex="-1">What to Avoid <a class="header-anchor" href="#what-to-avoid-1" aria-label="Permalink to &quot;What to Avoid&quot;">​</a></h3><ul><li><strong>Scripts that manipulate the platform DOM</strong> — Moving, reordering, or modifying elements rendered by the platform</li><li><strong>Scripts that rely on internal CSS class names</strong> — These change without notice during platform updates</li><li><strong>Heavy library imports</strong> — Loading full frameworks like jQuery or Bootstrap adds significant page weight and can conflict with the platform&#39;s own framework</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>When the platform ships updates (for example, changes to module loading), third-party scripts that depend on internal structure may break. The platform team cannot revert product improvements to preserve a custom script. If your script breaks after a platform update, the script needs to be updated.</p></div><p>For the practices that keep third-party scripts from blocking, breaking, or colliding with the page, see <a href="./defensive-scripts-and-includes.html">Writing Defensive Scripts and Includes</a>.</p><h2 id="ssi-header-and-footer" tabindex="-1">SSI Header and Footer <a class="header-anchor" href="#ssi-header-and-footer" aria-label="Permalink to &quot;SSI Header and Footer&quot;">​</a></h2><p>SSI (Server Side Include) header and footer customization is the recommended approach for brand-level changes like global navigation bars, footers, or announcement banners. It is the safest way to add persistent chrome without interfering with platform internals.</p><p>For the practices that keep header and footer includes isolated and resilient, see <a href="./defensive-scripts-and-includes.html">Writing Defensive Scripts and Includes</a>.</p><h2 id="writing-durable-extension-code" tabindex="-1">Writing Durable Extension Code <a class="header-anchor" href="#writing-durable-extension-code" aria-label="Permalink to &quot;Writing Durable Extension Code&quot;">​</a></h2><p>Choosing a safe customization tier is only half the picture. A few habits keep the code you do write clean enough to publish and stable enough to last:</p><ul><li><strong>Readable code publishes reliably.</strong> The automatic security scan flags heavily obfuscated code, so keep your source readable. Standard minification from bundlers like webpack, Vite, or esbuild is fine.</li><li><strong>Bundled dependencies outlast external URLs.</strong> Including a library in your repository avoids both the external-script check and the fragility of a third-party URL changing underneath you.</li><li><strong>Connectors keep credentials out of the browser.</strong> Routing external API calls through <a href="/docs/connectors/">Connectors</a> means no keys or tokens ever live in extension code — which is also what the credential scan enforces.</li><li><strong>Relative asset paths stay portable.</strong> Referencing CSS, JavaScript, and images with relative paths keeps them valid wherever the platform serves your extension.</li></ul><h2 id="what-happens-when-customizations-break" tabindex="-1">What Happens When Customizations Break <a class="header-anchor" href="#what-happens-when-customizations-break" aria-label="Permalink to &quot;What Happens When Customizations Break&quot;">​</a></h2><p>The platform evolves continuously. When a platform update affects a customization:</p><ul><li><strong>Safe-tier customizations</strong> continue to work. The platform maintains backward compatibility for supported configuration and the extension framework.</li><li><strong>Caution-tier customizations</strong> (scoped CSS, simple scripts) generally survive, but may occasionally need minor adjustments.</li><li><strong>Avoid-tier customizations</strong> (DOM manipulation, internal class dependencies) are likely to break and require rework. The platform team will not revert product changes to preserve unsupported customizations.</li></ul><p>When in doubt about whether a customization approach is safe, use the supported <a href="/docs/custom-widgets/v2/">Extensions</a> framework — widgets, scripts, and stylesheets are designed to survive platform updates.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="./defensive-scripts-and-includes.html">Writing Defensive Scripts and Includes</a> — Practices for scripts and header/footer includes that survive platform updates</li><li><a href="./content-security.html">Content Security</a> — Automatic security checks applied to your code</li><li><a href="./scripts.html">Script Definition Reference</a> — Add custom JavaScript to community pages</li><li><a href="./stylesheets.html">Stylesheet Definition Reference</a> — Add custom CSS to community pages</li><li><a href="/docs/connectors/">Connectors</a> — Route external API calls securely through the backend</li></ul>',45)])])}const m=e(s,[["render",i]]);export{p as __pageData,m as default};
